export function redact<T>(value: T, paths: readonly string[], replacement: unknown = "***"): T {
  const selected = new Set(paths);
  function visit(node: unknown, prefix: string): unknown {
    if (Array.isArray(node)) return node.map(item => visit(item, prefix));
    if (node !== null && typeof node === "object") {
      return Object.fromEntries(Object.entries(node).map(([key, child]) => {
        const path = prefix ? prefix + "." + key : key;
        return [key, selected.has(path) ? structuredClone(replacement) : visit(child, path)];
      }));
    }
    return node;
  }
  return visit(value, "") as T;
}
